import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { timingSafeEqual, randomBytes, createHash } from 'node:crypto';
import { db } from '../db/index.js';

const PORT=Number(process.env.ADMIN_WEB_PORT||8080);
const USERNAME=process.env.ADMIN_WEB_USERNAME||'admin';
const PASSWORD=process.env.ADMIN_WEB_PASSWORD||'';
const ADMIN_CHAT_ID=String(process.env.ADMIN_CHAT_ID||'').trim();
let sendOtp:(code:string)=>Promise<void>=async()=>{};
const SECTIONS={"settings":{"label":"Cài đặt","columns":["key","value","note"]},"tiktok":{"label":"Kết nối TikTok","columns":["business_center_id","read_token","write_token","note"]},"advertisers":{"label":"Tài khoản quảng cáo","columns":["advertiser_id","advertiser_name","market_code","enabled","note"]},"signer":{"label":"Đăng nhập TikTok","columns":["email","password","totp_secret","note"]},"sources":{"label":"Sheet doanh số","columns":["name","sheet_id","enabled","note"]},"products":{"label":"Tên sản phẩm","columns":["material_name","variant_name","campaign_key","enabled"]},"pages":{"label":"Page Mapping","columns":["page_handle","market_code","page_name","page_url","enabled"]},"ruler_auto":{"label":"Ruler Auto","columns":["entity","name_contains","metric","metric_operator","metric_threshold","metric_min_threshold","conversions_operator","conversions_threshold","action","campaign_status","enabled","note"]},"material_ruler":{"label":"Ruler Material","columns":["campaign_match","spend_operator","spend_threshold","cpa_operator","cpa_threshold","conversions_operator","conversions_threshold","enabled","note"]}} as const;
const SETTING_NAMES:Record<string,string>={balance_threshold_usd:'Ngưỡng cảnh báo số dư (USD)',exchange_rate:'Tỷ giá USD sang VND',level1_interval_minutes:'Chu kỳ kiểm tra cấp 1 (phút)',level2_cp_ads_threshold:'Ngưỡng % chi phí quảng cáo cấp 2',level2_interval_minutes:'Chu kỳ kiểm tra cấp 2 (phút)',level3_cp_ads_threshold:'Ngưỡng % chi phí quảng cáo cấp 3',level3_interval_minutes:'Chu kỳ kiểm tra cấp 3 (phút)',material_ruler_period:'Khoảng dữ liệu Ruler Material',material_ruler_run_time:'Giờ chạy Ruler theo lịch',sheets_concurrency:'Số tác vụ Sheet chạy đồng thời',tiktok_concurrency:'Số tác vụ TikTok chạy đồng thời',auto_action_mode:'Chế độ auto tắt/bật (Material/Campaign)'};
type Section=keyof typeof SECTIONS;

function sendJson(res:ServerResponse,status:number,data:unknown){const value=JSON.stringify(data);res.writeHead(status,{'content-type':'application/json; charset=utf-8'});res.end(value);}
function equal(a:string,b:string){const x=Buffer.from(a),y=Buffer.from(b);return x.length===y.length&&timingSafeEqual(x,y);}
async function auth(req:IncomingMessage,res:ServerResponse){const cookie=String(req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('admin_session='))?.slice(14);if(cookie){const now=Date.now();const row=await db.get<{token_hash:string;last_seen:number;expires_at:number}>('SELECT * FROM admin_sessions WHERE token_hash=?',[await hash(cookie)]);if(row&&row.expires_at>now&&now-row.last_seen<30*60*1000){await db.run('UPDATE admin_sessions SET last_seen=? WHERE token_hash=?',[now,row.token_hash]);return true;}}if(PASSWORD){const value=req.headers.authorization||'';try{if(value.startsWith('Basic ')){const [u,p]=Buffer.from(value.slice(6),'base64').toString().split(':');if(equal(u||'',USERNAME)&&equal(p||'',PASSWORD))return true;}}catch{}}res.writeHead(401,{'content-type':'application/json','www-authenticate':'Basic realm="TikTokSaleBot Admin"'});res.end(JSON.stringify({error:'login_required'}));return false;}
function validSection(value:string):value is Section{return Object.hasOwn(SECTIONS,value);}
async function readBody(req:IncomingMessage){let value='';for await(const chunk of req){value+=chunk;if(value.length>1_000_000)throw new Error('Dữ liệu quá lớn');}return value?JSON.parse(value):{};}
function normalize(section:Section,value:unknown){const input=value&&typeof value==='object'?value as Record<string,unknown>:{};const row:Record<string,string|number>={};for(const key of SECTIONS[section].columns){row[key]=key==='enabled'?(input[key]===true||['true','1','yes','on'].includes(String(input[key]??'').toLowerCase())?1:0):String(input[key]??'').trim();}return row;}
async function hash(value:string){return createHash('sha256').update(value).digest('hex');}
async function ensureAuthTables(){await db.exec(`CREATE TABLE IF NOT EXISTS admin_login_codes(id INTEGER PRIMARY KEY AUTOINCREMENT,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER,attempts INTEGER NOT NULL DEFAULT 0,requested_at INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS admin_sessions(token_hash TEXT PRIMARY KEY,created_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,expires_at INTEGER NOT NULL);`);try{await db.exec('ALTER TABLE admin_login_codes ADD COLUMN attempts INTEGER NOT NULL DEFAULT 0')}catch{}try{await db.exec('ALTER TABLE admin_login_codes ADD COLUMN requested_at INTEGER NOT NULL DEFAULT 0')}catch{} }
async function ensureTables(){await ensureAuthTables();await db.exec(`CREATE TABLE IF NOT EXISTS admin_config_rows(id INTEGER PRIMARY KEY AUTOINCREMENT,section TEXT NOT NULL,data_json TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_admin_config_rows_section ON admin_config_rows(section,position,id);
CREATE TABLE IF NOT EXISTS admin_audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,section TEXT NOT NULL,action TEXT NOT NULL,detail TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS admin_config_history(id INTEGER PRIMARY KEY AUTOINCREMENT,section TEXT NOT NULL,data_json TEXT NOT NULL,row_count INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_admin_config_history_section ON admin_config_history(section,id DESC);`);const defaults:Record<string,string>={level1_interval_minutes:'1',level2_interval_minutes:'59',level3_interval_minutes:'180',exchange_rate:'28119',balance_threshold_usd:'10',level2_cp_ads_threshold:'40',level3_cp_ads_threshold:'40',sheets_concurrency:'4',tiktok_concurrency:'5',material_ruler_run_time:'00:05',material_ruler_period:'today',auto_action_mode:'material'};for(const [key,value] of Object.entries(defaults))await db.run('INSERT OR IGNORE INTO bot_settings(key,value) VALUES(?,?)',[key,value]);
const legacy=await db.all<{id:number;data_json:string}>('SELECT id,data_json FROM admin_config_rows WHERE section=? ORDER BY id',['material_ruler']);
for(const row of legacy){try{const v=JSON.parse(row.data_json) as Record<string,unknown>;if(v.metric&&v.action){await db.run('INSERT INTO alert_action_rules(entity,name_contains,metric,metric_operator,metric_threshold,metric_min_threshold,conversions_operator,conversions_threshold,action,is_active,note) VALUES(?,?,?,?,?,?,?,?,?,?,?)',['material',String(v.name_contains||''),v.metric,v.metric_operator,Number(v.metric_threshold),v.metric_min_threshold?Number(v.metric_min_threshold):null,v.conversions_operator,Number(v.conversions_threshold),v.action,v.enabled===false?0:1,String(v.note||'')]);await db.run('DELETE FROM admin_config_rows WHERE id=?',[row.id]);}else if((v.period||v.run_time||v.timezone)&&!v.campaign_match){await db.run('DELETE FROM admin_config_rows WHERE id=?',[row.id]);}}catch{}}
}
async function getRows(section:Section){if(section==='settings'){const rows=await db.all<Record<string,unknown>>(`SELECT key,value,'' AS note,updated_at FROM bot_settings ORDER BY key`);return rows.map(row=>({...row,display_name:SETTING_NAMES[String(row.key)]||'Cài đặt tùy chỉnh'}));}if(section==='ruler_auto')return db.all(`SELECT id,entity,name_contains,metric,metric_operator,metric_threshold,metric_min_threshold,conversions_operator,conversions_threshold,action,campaign_status,is_active AS enabled,note,updated_at FROM alert_action_rules ORDER BY id`);const rows=await db.all<{id:number;data_json:string;updated_at:string}>('SELECT id,data_json,updated_at FROM admin_config_rows WHERE section=? ORDER BY position,id',[section]);return rows.map(row=>({id:row.id,...JSON.parse(row.data_json),updated_at:row.updated_at}));}
async function getReadiness(){const read=async(section:string)=>{const rows=await db.all<{data_json:string}>('SELECT data_json FROM admin_config_rows WHERE section=? ORDER BY position,id',[section]);return rows.map(row=>JSON.parse(row.data_json) as Record<string,unknown>)};const [tiktok,advertisers,signer,sources,products,pages,materialRules,actionRules]=await Promise.all([read('tiktok'),read('advertisers'),read('signer'),read('sources'),read('products'),read('pages'),read('material_ruler'),db.all<Record<string,unknown>>('SELECT entity,is_active FROM alert_action_rules')]);const first=tiktok[0]||{},login=signer[0]||{};const enabled=(rows:Record<string,unknown>[])=>rows.filter(row=>Number(row.enabled??1)!==0);const envAdvertisers=String(process.env.TIKTOK_ADVERTISER_IDS||'').split(',').map(value=>value.trim()).filter(Boolean);const advertiserCount=enabled(advertisers).length||envAdvertisers.length;const tiktokOk=Boolean((first.business_center_id||process.env.TIKTOK_BC_ID)&&(first.read_token||process.env.TIKTOK_READ_ACCESS_TOKEN)&&(first.write_token||process.env.TIKTOK_WRITE_ACCESS_TOKEN)),signerOk=Boolean((login.email||process.env.TIKTOK_ACCOUNT_EMAIL)&&(login.password||process.env.TIKTOK_ACCOUNT_PASSWORD)&&(login.totp_secret||process.env.TIKTOK_ACCOUNT_TOTP_SECRET));return {items:[{key:'tiktok',label:'Kết nối TikTok',ok:tiktokOk,detail:tiktokOk?'Đã đủ Business Center ID và 2 token':'Cần Business Center ID, token đọc và token ghi'},{key:'advertisers',label:'Tài khoản quảng cáo',ok:advertiserCount>0,detail:`${advertiserCount} tài khoản đã cấu hình`},{key:'signer',label:'Đăng nhập TikTok',ok:signerOk,detail:signerOk?'Đã đủ email, mật khẩu và mã bí mật 2FA':'Cần email, mật khẩu và mã bí mật 2FA'},{key:'sources',label:'Sheet doanh số',ok:enabled(sources).some(row=>row.sheet_id),detail:`${enabled(sources).length} nguồn đang dùng`},{key:'products',label:'Tên sản phẩm',ok:enabled(products).some(row=>row.variant_name&&row.campaign_key),detail:`${enabled(products).length} dòng đang dùng`},{key:'pages',label:'Page Mapping',ok:enabled(pages).some(row=>row.page_handle&&row.market_code),detail:`${enabled(pages).length} dòng đang dùng`},{key:'ruler_auto',label:'Ruler Auto',ok:actionRules.some(row=>Number(row.is_active)!==0),detail:`${actionRules.filter(row=>Number(row.is_active)!==0).length} rule đang dùng`},{key:'material_ruler',label:'Ruler Material',ok:enabled(materialRules).length>0,detail:`${enabled(materialRules).length} rule đang dùng`} ]};}
async function putRows(section:Section,items:unknown[]){const previousRows=await getRows(section);await db.exec('BEGIN IMMEDIATE');try{await db.run('INSERT INTO admin_config_history(section,data_json,row_count) VALUES(?,?,?)',[section,JSON.stringify(previousRows),previousRows.length]);if(section==='settings'){for(const item of items){const r=normalize(section,item);if(!r.key)continue;await db.run(`INSERT INTO bot_settings(key,value,updated_at) VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=CURRENT_TIMESTAMP`,[r.key,r.value]);}}else if(section==='ruler_auto'){await db.run('DELETE FROM alert_action_rules');for(const item of items){const r=normalize(section,item);await db.run(`INSERT INTO alert_action_rules(entity,name_contains,metric,metric_operator,metric_threshold,metric_min_threshold,conversions_operator,conversions_threshold,action,campaign_status,is_active,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`,[r.entity,r.name_contains||null,r.metric,r.metric_operator,Number(r.metric_threshold),r.metric_min_threshold===''?null:Number(r.metric_min_threshold),r.conversions_operator,Number(r.conversions_threshold),r.action,r.campaign_status||null,r.enabled,r.note||null]);}}else{await db.run('DELETE FROM admin_config_rows WHERE section=?',[section]);let position=0;for(const item of items)await db.run('INSERT INTO admin_config_rows(section,data_json,position) VALUES(?,?,?)',[section,JSON.stringify(normalize(section,item)),position++]);}await db.run('INSERT INTO admin_audit_log(section,action,detail) VALUES(?,?,?)',[section,'save',String(items.length)+' dòng']);await db.run('DELETE FROM admin_config_history WHERE section=? AND id NOT IN (SELECT id FROM admin_config_history WHERE section=? ORDER BY id DESC LIMIT 30)',[section,section]);await db.exec('COMMIT');}catch(error){await db.exec('ROLLBACK');throw error;}}

